// Loads the project's own display face (public/assets/fonts, generated by src/ui/fonts/build_font.py).
export const DISPLAY_FONT = '"RFT Display"';
export const TEXT_FONT = 'system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';

let loading: Promise<void> | null = null;

/** Resolve a file in public/ against the app base (works for dev, sub-path deploys and file previews). */
export function publicUrl(path: string): string {
  const base = (import.meta.env?.BASE_URL as string | undefined) ?? '/';
  return (base.endsWith('/') ? base : base + '/') + path.replace(/^\//, '');
}

export function loadFonts(): Promise<void> {
  if (loading) return loading;
  if (typeof FontFace === 'undefined' || typeof document === 'undefined') return (loading = Promise.resolve());
  const faces = [400, 600, 800].map((w) => new FontFace('RFT Display', `url(${publicUrl(`assets/fonts/rft-display-${w}.woff`)}) format("woff")`, { weight: String(w), display: 'block' }));
  loading = Promise.all(faces.map((f) => f.load().then((ff) => { document.fonts.add(ff); }).catch(() => { /* fallback font */ })))
    .then(() => undefined);
  return loading;
}
